/* Tekrar havuzu: cond-types, cond-mixed, cond-alt, wish, inv */
PRACTICE.push(
  {id:"r-cond-types-01", sub:"cond-types", from:["cond-01"], q:"If plants ---- too little light, they produce less chlorophyll and their leaves gradually turn yellow.", o:["will receive","receive","received","would receive","had received"], a:1, e:"Ana cümle geniş zamanda (produce, turn) ve genel bir bilimsel gerçek anlatılıyor; Type 0 olduğundan if kısmı da present: receive. will receive if cümleciğinde kullanılmaz; received Type 2'ye aittir ve geniş zamanlı sonuçla uyuşmaz."},
  {id:"r-cond-types-02", sub:"cond-types", from:["cond-01"], q:"If iron ---- exposed to oxygen and moisture for long periods, it rusts and gradually loses its strength.", o:["will be","was","would be","is","had been"], a:3, e:"Paslanma her zaman geçerli bilimsel bir gerçektir ve ana cümle present (rusts, loses); Type 0: if + present (is). will be if cümleciğinde kullanılmaz; was ise hayali bir durum (Type 2) bildirir."},
  {id:"r-cond-types-03", sub:"cond-types", from:["cond-02"], q:"If the negotiations ---- by Friday, the union ---- a nationwide strike next week.", o:["fail / will call","failed / will call","will fail / calls","had failed / would call","fail / would have called"], a:0, e:"“by Friday” ve “next week” gerçekleşmesi olası bir geleceği gösterir; Type 1: fail / will call. “failed / will call” iki farklı koşul türünü karıştırır; will if cümleciğinin içinde kullanılmaz."},
  {id:"r-cond-types-04", sub:"cond-types", from:["cond-02"], q:"If sea levels continue to rise at the current rate, several low-lying island nations ---- uninhabitable by the end of the century.", o:["would have become","became","had become","may become","would become"], a:3, e:"if kısmı present (continue) ve anlam gerçekçi bir gelecek tahmini; Type 1 sonucu will / may + V ister: may become. would become Type 2 sonucudur ve present koşulla uyuşmaz; would have become geçmişe aittir."},
  {id:"r-cond-types-05", sub:"cond-types", from:["cond-02","cond-01"], q:"If you ---- any unusual symptoms after taking the medication, stop using it and contact your doctor immediately.", o:["will notice","notice","noticed","had noticed","would notice"], a:1, e:"Ana cümle emir kipinde (stop, contact) ve olası bir gelecek durumdan söz ediyor; if kısmında present simple gelir: notice. will notice ve would notice if cümleciğinin içinde kullanılmaz; had noticed geçmişe ait hayali bir koşuldur."},
  {id:"r-cond-types-06", sub:"cond-types", from:["cond-04"], q:"If the Earth ---- no atmosphere, its average surface temperature ---- far below freezing.", o:["has / will be","had had / would have been","would have / was","has had / would be","had / would be"], a:4, e:"Dünya'nın atmosferi var; bu gerçeğe aykırı, zamandan bağımsız bir hayal olduğu için Type 2: had / would be. “has / will be” gerçek bir olasılık gibi davranır; “had had / would have been” ise geçmişteki tek bir olaya aittir."},
  {id:"r-cond-types-07", sub:"cond-types", from:["cond-04"], q:"If I ---- in your position, I would seek legal advice before signing the contract.", o:["am","had been","would be","were","will be"], a:3, e:"Ana cümle would + V (would seek) ile şimdiki hayali bir durumu anlatır; Type 2'de if kısmı past olur ve be fiili için were kullanılır. had been Type 3'e aittir; would be ve will be if cümleciğinde kullanılmaz."},
  {id:"r-cond-types-08", sub:"cond-types", from:["cond-04"], q:"Many small farmers ---- their yields considerably if they had access to modern irrigation technology, but most of them cannot afford it.", o:["could increase","can increase","could have increased","will increase","had increased"], a:0, e:"“but most of them cannot afford it” koşulun şu anda gerçekleşmediğini gösterir; if + past (had) ile Type 2 sonucu could + V: could increase. could have increased geçmişe ait olup present gerçekle çelişir; can / will increase Type 1 sonucudur."},
  {id:"r-cond-types-09", sub:"cond-types", from:["cond-03"], q:"If the ship's crew ---- the iceberg earlier, the disaster ---- in 1912.", o:["spotted / would be avoided","spot / will be avoided","had spotted / might be avoided","had spotted / might have been avoided","would spot / had been avoided"], a:3, e:"“in 1912” iki eylemin de geçmişte kaldığını gösterir; Type 3: had spotted / might have been avoided. “had spotted / might be avoided” şimdiki bir sonuç bildirdiği için 1912 ile uyuşmaz."},
  {id:"r-cond-types-10", sub:"cond-types", from:["cond-03"], q:"The company ---- bankrupt last year if the government had not provided an emergency loan.", o:["would have gone","would go","will go","had gone","went"], a:0, e:"if kısmı had not provided (Type 3) ve “last year” geçmişi gösterir; sonuç would have V3 olmalıdır: would have gone. would go şimdiki bir sonuç bildirir ve last year ile çelişir; had gone ana cümlede koşul sonucu olamaz."},
  {id:"r-cond-types-11", sub:"cond-types", from:["cond-03"], q:"If the polio vaccine ---- more widely in the 1950s, far fewer children would have been left disabled by the disease.", o:["was distributed","were distributed","would have been distributed","has been distributed","had been distributed"], a:4, e:"Ana cümle would have been left (Type 3) ve “in the 1950s” geçmişi gösterir; if kısmı had + V3 (edilgen: had been distributed) olur. were distributed Type 2 yapısıdır; would have been distributed if cümleciğinin içinde kullanılmaz."},
  {id:"r-cond-types-12", sub:"cond-types", from:["cond-04"], q:"If more people ---- public transport these days, air pollution in large cities ---- such a serious health problem.", o:["use / will not be","used / would not be","had used / would not have been","would use / were not","have used / would not be"], a:1, e:"“these days” şimdiki gerçeğe aykırı bir durumu anlatır (insanlar yeterince toplu taşıma kullanmıyor); Type 2: used / would not be. “had used / would not have been” geçmişe aittir; would if cümleciğinde kullanılmaz."},
  {id:"r-cond-types-13", sub:"cond-types", from:["w4-03","cond-03"], q:"If the Wright brothers had given up after their early failures, ----.", o:["aircraft are now used by millions of passengers every day","they will be remembered as the pioneers of aviation","they had designed a much lighter engine","powered flight might not have been achieved as early as 1903","air travel becomes cheaper every year"], a:3, e:"“had given up” Type 3 koşuldur ve “might / would (not) have + V3” ister; vazgeçselerdi 1903'te motorlu uçuş gerçekleşmeyebilirdi. “they will be remembered” Type 1 sonucudur; “had designed” ise koşul cümlesinin sonucu olamaz."},
  {id:"r-cond-types-14", sub:"cond-types", from:["cond-02","w4-03"], q:"If the current drought continues into the summer, ----.", o:["water restrictions will probably be introduced in several provinces","farmers would have lost most of their crops","the reservoirs had already dried up","the government would not have raised food prices","rainfall was well above average last year"], a:0, e:"if kısmı present (continues) ve gerçekçi bir gelecek olasılığı bildirir; Type 1 sonucu will + V ister: su kısıtlamaları getirilecek. “would have lost” Type 3 sonucudur ve present koşulla uyuşmaz."},
  {id:"r-cond-types-15", sub:"cond-types", from:["cond-04","w4-03"], q:"If antibiotics were no longer effective against common infections, ----.", o:["doctors will prescribe them more carefully","many patients had died of minor wounds","the risk of infection has been reduced","bacteria develop resistance more quickly","even routine surgical operations would become extremely risky"], a:4, e:"“were no longer effective” şimdiki gerçeğe aykırı bir hayaldir (Type 2) ve would + V ister: basit ameliyatlar bile riskli hâle gelirdi. “will prescribe” Type 1 sonucudur; “had died” koşul cümlesinin sonucu olamaz."},
  {id:"r-cond-types-16", sub:"cond-types", from:["cond-01"], q:"If the human body loses too much water, ----.", o:["it would have suffered heat stroke","its organs had stopped working","dehydration would never occur","doctors will have recommended more salt","its ability to regulate its own temperature declines"], a:4, e:"Vücutla ilgili genel bir gerçek anlatılıyor ve if kısmı present (loses); Type 0 sonucu da present olur: sıcaklık düzenleme yeteneği azalır. “would have suffered” Type 3 sonucudur; “dehydration would never occur” anlamca çelişkilidir."},
  {id:"r-cond-types-17", sub:"cond-types", from:["cond-03"], q:"If the museum's alarm system ---- properly on the night of the robbery, the thieves could not have entered the building unnoticed.", o:["worked","would have worked","had worked","works","has worked"], a:2, e:"Ana cümle could not have entered (Type 3) ve “on the night of the robbery” geçmişi gösterir; if kısmı had V3 olur: had worked. worked Type 2 koşuludur; would have worked if cümleciğinde kullanılmaz."},
  {id:"r-cond-types-18", sub:"cond-types", from:["cond-02"], q:"If the proposed law ---- by parliament next month, online retailers ---- to disclose the origin of all their products.", o:["will be passed / are required","is passed / will be required","was passed / would have been required","passed / will be required","had been passed / would require"], a:1, e:"“next month” gerçekçi bir gelecek bildirir; Type 1: is passed / will be required (edilgen). “will be passed” if cümleciğinde kullanılmaz; “passed / will be required” Type 2 koşulu ile Type 1 sonucunu karıştırır."},
  {id:"r-cond-types-19", sub:"cond-types", from:["cond-04"], q:"If the region ---- better roads and ports, it ---- far more foreign investment than it currently does.", o:["has / attracted","had had / might have attracted","had / might attract","would have / attracts","has / might have attracted"], a:2, e:"“than it currently does” bölgenin şu anki durumuna aykırı bir hayal kurulduğunu gösterir; Type 2: had / might attract. “had had / might have attracted” geçmişe aittir ve currently ile çelişir."},
  {id:"r-cond-types-20", sub:"cond-types", from:["cond-03"], q:"If the archaeologists ---- the site so carefully during the 1998 season, they ---- the tiny fragments of ancient textile.", o:["did not excavate / would never find","had not excavated / will never find","had not excavated / would never have found","have not excavated / would never find","would not excavate / had never found"], a:2, e:"“during the 1998 season” kazının geçmişte yapıldığını gösterir; geçmişe aykırı durum Type 3: had not excavated / would never have found. “had not excavated / will never find” koşul türlerini karıştırır; would if kısmında kullanılmaz."},
  {id:"r-cond-types-21", sub:"cond-types", from:["cond-02","cond-01"], q:"If a patient ---- a rare blood type, the hospital ---- difficulty finding a suitable donor in an emergency.", o:["had / will have","has / may have","has had / would have","would have / has","had had / may have"], a:1, e:"Genel ve gerçekleşmesi olası bir durum anlatılıyor; if + present, sonuç may + V: has / may have. “had / will have” Type 2 koşulunu Type 1 sonucuyla karıştırır; would if cümleciğinde kullanılmaz."},
  {id:"r-cond-types-22", sub:"cond-types", from:["cond-04"], q:"If the Moon did not exist, the Earth's axis ---- much less stable and its climate would change far more dramatically.", o:["would be","will be","would have been","is","had been"], a:0, e:"Ay var; bu kalıcı gerçeğe aykırı hayal Type 2'dir (did not exist) ve cümlenin devamındaki would change ile paralel olarak would + V gerekir: would be. would have been geçmişteki tek bir olaya ait sonuç bildirir."},
  {id:"r-cond-types-23", sub:"cond-types", from:["cond-03"], q:"The two companies might have avoided a costly legal dispute if they ---- the terms of their agreement more clearly.", o:["had defined","defined","would define","have defined","define"], a:0, e:"Ana cümle might have avoided (Type 3) geçmişteki bir anlaşmazlığı anlatır; if kısmı had V3 olmalıdır: had defined. defined Type 2 koşuludur ve might have V3 ile uyumsuzdur; would if kısmında kullanılmaz."},
  {id:"r-cond-types-24", sub:"cond-types", from:["cond-03"], passage:"In 1854, a cholera outbreak killed hundreds of people in the Soho district of London. The physician John Snow noticed that most of the victims had drawn their water from a single public pump on Broad Street. He persuaded local officials to remove the pump's handle, and the number of new cases soon fell. Many historians argue that if Snow (1) ---- the pattern of deaths so carefully, the link between contaminated water and cholera would have remained unproven for many more years. His work is now regarded as one of the foundations of modern epidemiology.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["did not map","would not have mapped","had not mapped","has not mapped","does not map"], a:2, e:"Ana cümle would have remained (Type 3) ve olay 1854'te yaşanmıştır; if kısmı had V3 olur: had not mapped. did not map Type 2 koşuludur ve geçmiş sonuçla uyuşmaz; would not have mapped if cümleciğinde kullanılmaz."},
  {id:"r-cond-types-25", sub:"cond-types", from:["cond-04"], passage:"Solar storms are powerful bursts of energy and charged particles released by the Sun. When such particles reach the Earth, they can disrupt satellites, radio communications and even electricity grids. The strongest storm ever recorded occurred in 1859, when telegraph systems across Europe and North America failed. At that time, few people relied on electricity. According to a recent report, however, if a storm of similar strength (1) ---- the planet today, it would cause widespread power cuts and economic losses worth trillions of dollars.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["strikes","had struck","would strike","has struck","struck"], a:4, e:"Ana cümle would cause ve “today” şimdiki/gelecek hayali bir durumu gösterir; Type 2'de if kısmı past olur: struck. strikes Type 1 koşuludur ve would ile uyuşmaz; had struck geçmişe ait Type 3 koşuludur."},
  {id:"r-cond-types-26", sub:"cond-types", from:["w4-03","cond-03"], q:"----, the expedition would not have reached the summit before the storm arrived.", o:["If the climbers do not set off before dawn","If the climbers set off before dawn","If the climbers had not set off before dawn","Since the climbers had started out before dawn","When the storm is approaching"], a:2, e:"Ana cümle would not have reached (Type 3) geçmişe ait bir sonuçtur ve had V3 koşulu ister: şafaktan önce yola çıkmasalardı zirveye ulaşamazlardı. “If the climbers set off before dawn” zaman olarak uyuşmaz; “Since the climbers had started out …” ise anlamı mantıksız kılar."},
  {id:"r-cond-types-27", sub:"cond-types", from:["cond-04"], q:"If the company ---- its prices, it ---- many of its loyal customers, so the management has decided not to change them next year.", o:["raises / would lose","raised / would lose","had raised / would have lost","would raise / lost","raised / will have lost"], a:1, e:"Yönetim fiyatları gelecek yıl değiştirmemeye karar verdiği için fiyat artışı gerçekleşmeyecek hayali bir durumdur; Type 2: raised / would lose. “raises / would lose” koşul türlerini karıştırır; “had raised / would have lost” geçmişe aittir ve next year ile uyuşmaz."},
  {id:"r-cond-mixed-01", sub:"cond-mixed", from:["cond-05"], q:"If early settlers ---- rabbits to the island in the 1800s, its native vegetation ---- in much better condition today.", o:["did not introduce / would be","had not introduced / would have been","do not introduce / will be","had not introduced / would be","would not introduce / had been"], a:3, e:"“in the 1800s” geçmiş sebebi, “today” şimdiki sonucu gösterir; mixed conditional: had not introduced / would be. “would have been” today ile uyuşmadığı için en çekici çeldiricidir."},
  {id:"r-cond-mixed-02", sub:"cond-mixed", from:["cond-05"], q:"If she ---- medicine instead of law twenty years ago, she ---- in a hospital rather than a courtroom now.", o:["studied / would be working","had studied / would have worked","studies / will work","would study / had worked","had studied / would be working"], a:4, e:"“twenty years ago” geçmişteki kararı, “now” bugünkü sonucu gösterir; had studied / would be working. “studied / would be working” geçmiş zaman ifadesiyle uyumsuzdur; “would have worked” ise now ile çelişir."},
  {id:"r-cond-mixed-03", sub:"cond-mixed", from:["cond-05","cond-07"], q:"If the dam ---- in the 1970s, the valley ---- still home to dozens of traditional villages.", o:["was not built / would have been","had not been built / would have been","had not been built / would be","were not built / will be","has not been built / would be"], a:2, e:"Baraj geçmişte yapıldı (“in the 1970s”), sonuç ise bugüne ait (“still”); had not been built / would be. “would have been” still ile anlatılan şimdiki durumla uyuşmaz."},
  {id:"r-cond-mixed-04", sub:"cond-mixed", from:["cond-06"], q:"If he ---- so stubborn, he ---- his colleagues' advice at yesterday's meeting.", o:["had not been / would listen to","were not / would have listened to","is not / will listen to","were not / would listen to","would not be / had listened to"], a:1, e:"İnatçılık genel/kalıcı bir kişilik özelliğidir (Type 2 koşul), toplantı ise dün yapıldı (Type 3 sonuç): were not / would have listened to. “were not / would listen to” yesterday ile uyumsuzdur."},
  {id:"r-cond-mixed-05", sub:"cond-mixed", from:["cond-06"], q:"If the country ---- so dependent on a single export, the collapse in copper prices last year ---- such a severe recession.", o:["had not been / would not cause","is not / will not cause","were not / would not cause","were not / would not have caused","would not be / did not cause"], a:3, e:"Tek ürüne bağımlılık süregelen bir durumdur (Type 2 koşul), çöküş ise geçen yıl yaşandı (Type 3 sonuç): were not / would not have caused. “would not cause” last year ile uyuşmaz; would if kısmında kullanılmaz."},
  {id:"r-cond-mixed-06", sub:"cond-mixed", from:["cond-07"], q:"Had the ancient Library of Alexandria not been destroyed, historians ---- far more about the classical world today.", o:["would have known","will know","had known","would know","knew"], a:3, e:"Had … V3 geçmiş koşuldur ama “today” şimdiki sonucu gösterir; mixed yapı: would know. would have known geçmiş sonuç bildirir ve today ile çelişir."},
  {id:"r-cond-mixed-07", sub:"cond-mixed", from:["cond-07"], q:"Had the company invested in digital technology a decade ago, it ---- to compete with its online rivals now.", o:["would not have been struggling","will not struggle","had not struggled","did not struggle","would not be struggling"], a:4, e:"Devrik Had … V3 geçmişteki bir kararı, “now” bugünkü sonucu gösterir; mixed yapı: would not be struggling. “would not have been struggling” geçmişe ait bir sonuçtur ve now ile uyuşmaz."},
  {id:"r-cond-mixed-08", sub:"cond-mixed", from:["cond-05","cond-07"], q:"If the company had not relocated its headquarters to Singapore in 2010, ----.", o:["it would probably be a much smaller regional firm today","it will expand into Asian markets next year","its profits had been rising steadily","it would open new offices in Europe last year","its employees are happier with their working conditions"], a:0, e:"Koşul geçmişe (in 2010) ait, sonuç ise bugüne (today); mixed yapı would + V ister: bugün çok daha küçük bir şirket olurdu. “would open … last year” would + V yapısını geçmiş zaman ifadesiyle kullandığı için hatalıdır; “will expand” Type 1 sonucudur."},
  {id:"r-cond-mixed-09", sub:"cond-mixed", from:["cond-06"], q:"If she were a more confident speaker, ----.", o:["she would have volunteered to present the findings at last month's conference","she will give the opening speech at next year's conference","she had delivered the keynote address last month","she avoided speaking in public","she would have felt anxious during last month's presentation"], a:0, e:"Özgüven eksikliği süregelen bir özelliktir (Type 2 koşul); sonucu geçmişteki bir olaya aittir: geçen ayki konferansta sunum yapmaya gönüllü olurdu. “would have felt anxious” yapıca uygun olsa da anlamca çelişkilidir; daha özgüvenli biri kaygı duymazdı."},
  {id:"r-cond-mixed-10", sub:"cond-mixed", from:["cond-05"], q:"If our ancestors ---- to cook their food hundreds of thousands of years ago, humans ---- such large brains today.", o:["did not learn / would not have had","had not learned / would not have had","do not learn / will not have","had not learned / would not have","would not learn / did not have"], a:3, e:"Geçmişteki bir gelişmenin (hundreds of thousands of years ago) bugünkü sonucu (today) anlatılıyor; had not learned / would not have (such large brains). “would not have had” geçmiş sonuç bildirir ve today ile uyuşmaz."},
  {id:"r-cond-mixed-11", sub:"cond-mixed", from:["cond-05"], q:"If the witness ---- the suspect's face clearly last night, the police ---- a detailed description to work with now.", o:["saw / would have had","had seen / would have had","had seen / would have","sees / will have","would see / had had"], a:2, e:"“last night” geçmiş koşulu, “now” bugünkü sonucu gösterir; had seen / would have (a description). “had seen / would have had” Type 3 sonucudur ve now ile çelişir."},
  {id:"r-cond-mixed-12", sub:"cond-mixed", from:["cond-06"], q:"If Maria ---- afraid of flying, she ---- to the conference in Tokyo last week instead of sending her assistant.", o:["had not been / would travel","were not / would have travelled","is not / will travel","were not / would travel","was not / had travelled"], a:1, e:"Uçma korkusu kalıcı bir durumdur (Type 2 koşul), konferans ise geçen hafta yapıldı (Type 3 sonuç): were not / would have travelled. “were not / would travel” last week ile uyuşmaz."},
  {id:"r-cond-mixed-13", sub:"cond-mixed", from:["cond-05"], q:"If the scientists ---- such a small sample in their original study, their conclusions ---- more widely accepted now.", o:["did not use / would have been","had not used / would have been","do not use / will be","would not use / were","had not used / would be"], a:4, e:"Çalışma geçmişte yapıldı (original study), sonuç ise bugüne ait (now); had not used / would be. “would have been” now ile uyumsuz olduğu için yanlıştır."},
  {id:"r-cond-mixed-14", sub:"cond-mixed", from:["cond-06"], q:"If the town ---- on a major trade route, it ---- into a prosperous city in the Middle Ages.", o:["had not been located / would not develop","were not located / would not have developed","is not located / will not develop","were not located / would not develop","would not be located / had not developed"], a:1, e:"Kasabanın konumu kalıcı bir gerçektir (Type 2 koşul), gelişme ise Orta Çağ'da oldu (Type 3 sonuç): were not located / would not have developed. “would not develop” geçmişe ait sonucu veremez."},
  {id:"r-cond-mixed-15", sub:"cond-mixed", from:["cond-07"], q:"Had the environmental treaty been ratified in 2015, the region's forests ---- in a much healthier state now.", o:["would have been","will be","had been","would be","are"], a:3, e:"Devrik Had … V3 geçmiş koşuldur (2015) ama “now” şimdiki sonucu gösterir; mixed yapı: would be. would have been geçmiş sonuç bildirir ve now ile çelişir."},
  {id:"r-cond-mixed-16", sub:"cond-mixed", from:["cond-05","cond-07"], passage:"Latin was once the common language of administration and learning across much of Europe. After the collapse of the Western Roman Empire, however, the spoken Latin of different regions gradually developed into separate languages such as Italian, Spanish and French. Some linguists speculate that if a single powerful state (1) ---- control over the whole region during the early Middle Ages, Europeans might still be speaking a common Latin-based language today. Others argue that local dialects would have diverged anyway, since communication between distant communities was slow and difficult.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["maintained","had maintained","would maintain","has maintained","maintains"], a:1, e:"Koşul geçmişe (during the early Middle Ages), sonuç bugüne (might still be speaking … today) aittir; mixed yapıda if kısmı had V3 olur: had maintained. maintained Type 2 koşuludur ve geçmiş zaman ifadesiyle uyuşmaz."},
  {id:"r-cond-mixed-17", sub:"cond-mixed", from:["cond-06"], passage:"Many people ignore the early warning signs of illness. A recent medical journal described the case of a 55-year-old office worker who had suffered from mild chest pains for several months. Being extremely reluctant to visit doctors, he kept postponing a check-up, and last spring he was rushed to hospital with a serious heart attack. He survived, but he still refuses most follow-up appointments. His cardiologist remarked that if the patient (1) ---- so distrustful of the medical profession, he would have sought help long before the attack occurred.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["is not","would not be","has not been","will not be","were not"], a:4, e:"Hastanın doktorlara güvensizliği hâlâ süren bir özelliktir (he still refuses), sonuç ise geçmişe aittir (would have sought); mixed yapıda koşul Type 2: were not. is not Type 1 koşuludur; would if cümleciğinde kullanılmaz."},
  {id:"r-cond-mixed-18", sub:"cond-mixed", from:["cond-06"], q:"If the region ---- so prone to earthquakes, the architects ---- such an expensive foundation for the new hospital last year.", o:["had not been / would not design","is not / will not design","were not / would not have designed","were not / would not design","would not be / had not designed"], a:2, e:"Depreme yatkınlık bölgenin kalıcı özelliğidir (Type 2 koşul), temel tasarımı ise geçen yıl yapıldı (Type 3 sonuç): were not / would not have designed. “would not design” last year ile uyuşmaz."},
  {id:"r-cond-mixed-19", sub:"cond-mixed", from:["cond-07"], q:"Had the two companies not merged in 2012, ----.", o:["neither of them would be a major player in the global market today","both of them would become more profitable last year","they will compete with each other for customers","their shares had lost value","the merger is considered a success"], a:0, e:"Devrik Had … V3 geçmiş koşuldur, sonuç ise bugüne aittir: bugün hiçbiri küresel pazarda büyük bir oyuncu olmazdı. “would become … last year” would + V'yi geçmiş zaman ifadesiyle kullandığı için hatalıdır; “will compete” Type 1 sonucudur."},
  {id:"r-cond-mixed-20", sub:"cond-mixed", from:["cond-05"], q:"If you ---- me the truth at the beginning, we ---- in this difficult situation now.", o:["told / would not have been","had told / would not have been","tell / will not be","would tell / were not","had told / would not be"], a:4, e:"“at the beginning” geçmişte olmayan bir eylemi, “now” bugünkü sonucu gösterir; had told / would not be. “would not have been” now ile çelişir."},
  {id:"r-cond-mixed-21", sub:"cond-mixed", from:["cond-06"], q:"If the cave ---- so difficult to reach, its prehistoric paintings ---- long before 1994.", o:["had not been / would be discovered","is not / will be discovered","were not / would have been discovered","were not / would be discovered","would not be / had been discovered"], a:2, e:"Mağaranın ulaşılmazlığı kalıcı bir özelliktir (Type 2 koşul), keşif ise geçmişe aittir (long before 1994): were not / would have been discovered. “would be discovered” geçmiş sonucu veremez."},
  {id:"r-cond-mixed-22", sub:"cond-mixed", from:["cond-06"], q:"If the patient were not allergic to penicillin, the doctors ---- it to treat his infection last week instead of a less effective drug.", o:["would have prescribed","would prescribe","will prescribe","had prescribed","prescribed"], a:0, e:"Alerji kalıcı bir durumdur (were not, Type 2 koşul), tedavi ise geçen hafta yapıldı; sonuç Type 3 olur: would have prescribed. would prescribe last week ile uyuşmaz; had prescribed koşul sonucu olamaz."},
  {id:"r-cond-mixed-23", sub:"cond-mixed", from:["cond-05"], q:"If the investors ---- the warning signs in 2007, many of them ---- still paying off their debts today.", o:["heeded / would not have been","had heeded / would not have been","had heeded / would not be","heed / will not be","would heed / were not"], a:2, e:"Uyarılar 2007'de göz ardı edildi, sonuç bugüne ait (still … today); had heeded / would not be (paying). “would not have been” today ile uyumsuzdur."},
  {id:"r-cond-mixed-24", sub:"cond-mixed", from:["cond-05"], q:"----, she would be fluent in Japanese by now.", o:["If she had continued her language classes after returning from Tokyo","If she continues her language classes","Although she had lived in Tokyo for three years","If she takes an intensive course next summer","Because she had never studied the language"], a:0, e:"Ana cümle bugüne ait bir hayal kurar (would be … by now); geçmişteki bir eylemi hayal eden had V3 koşulu gerekir: dönüşten sonra derslere devam etseydi. “If she continues …” Type 1 koşuludur ve would ile uyuşmaz; although ve because anlamı bozar."},
  {id:"r-cond-mixed-25", sub:"cond-mixed", from:["cond-06"], q:"----, he would have applied for the managerial position that was advertised last month.", o:["If he is more ambitious","If he were more ambitious","If he will be more ambitious","Since he was not interested in leadership","Unless he were more ambitious"], a:1, e:"Hırs kalıcı bir kişilik özelliğidir (Type 2 koşul), başvuru ise geçen ayki ilana aittir (Type 3 sonuç): If he were more ambitious. will if kısmında kullanılmaz; “Unless he were more ambitious” anlamı tersine çevirir."},
  {id:"r-cond-mixed-26", sub:"cond-mixed", from:["cond-05"], q:"If he ---- smoking as a teenager, his lungs ---- in much better condition now.", o:["did not start / would have been","had not started / would have been","had not started / would be","does not start / will be","would not start / were"], a:2, e:"“as a teenager” geçmiş sebebi, “now” bugünkü sonucu gösterir; had not started / would be. “would have been” now ile çelişir; “did not start” geçmiş zaman ifadesiyle Type 2 koşulu olamaz."},
  {id:"r-cond-mixed-27", sub:"cond-mixed", from:["cond-05","cond-07"], q:"If the ancient Greeks ---- the idea of democracy, modern political systems ---- very different from what they are today.", o:["did not develop / might have been","had not developed / might have been","do not develop / may be","had not developed / might be","would not develop / had been"], a:3, e:"Demokrasi fikri geçmişte geliştirildi, sonuç ise bugünkü siyasal sistemlerle ilgilidir (what they are today); had not developed / might be. “might have been” geçmiş sonuç bildirir ve today ile uyuşmaz."},
  {id:"r-cond-alt-01", sub:"cond-alt", from:["cond-08"], q:"The new vaccine will not be approved ---- clinical trials confirm that it is both safe and effective.", o:["provided that","in case","as long as","but for","unless"], a:4, e:"Anlam “denemeler güvenli olduğunu doğrulamazsa onaylanmayacak” olmalıdır; unless = if not. provided that / as long as “doğrularsa onaylanmayacak” gibi mantıksız bir anlam verir; but for ardından isim alır."},
  {id:"r-cond-alt-02", sub:"cond-alt", from:["cond-11"], q:"---- the river bursts its banks again this spring, the council has placed sandbags along the main streets.", o:["Unless","Provided that","But for","Otherwise","In case"], a:4, e:"Kum torbaları olası bir taşkına karşı alınmış bir önlemdir: in case (= olur da … diye). provided that anlamı şarta bağlar ve mantığı bozar; but for ardından isim alır."},
  {id:"r-cond-alt-03", sub:"cond-alt", from:["cond-09"], q:"Visitors can enter the laboratory ---- they wear protective clothing and are accompanied by a member of staff.", o:["unless","as long as","in case","otherwise","but for"], a:1, e:"Laboratuvara giriş bir şarta bağlanıyor: as long as (= şartıyla, sürece). unless anlamı tersine çevirir; in case önlem bildirir; otherwise iki cümleyi “aksi takdirde” anlamıyla bağlar."},
  {id:"r-cond-alt-04", sub:"cond-alt", from:["cond-10"], q:"---- the support of international donors, the reconstruction of the earthquake-hit city would have taken decades.", o:["Unless","Provided that","In case","Without","As long as"], a:3, e:"Boşluktan sonra isim öbeği var ve ana cümle Type 3; “… olmasaydı” anlamındaki Without (+ isim) gerekir. Unless, provided that, in case ve as long as ardından tam cümle ister."},
  {id:"r-cond-alt-05", sub:"cond-alt", from:["cond-11","cond-08"], q:"Students must submit their assignments by Friday; ----, they will lose ten percent of their marks.", o:["otherwise","unless","provided that","in case","as long as"], a:0, e:"Noktalı virgülden sonra “aksi takdirde” anlamı gerekir: otherwise. unless, provided that, in case ve as long as bağlaçtır ve ardından bir yan cümle ister; burada doğrudan virgül ve ana cümle geliyor."},
  {id:"r-cond-alt-06", sub:"cond-alt", from:["cond-09"], q:"---- you were offered a well-paid job abroad, would you be willing to leave your family behind?", o:["Unless","Supposing","In case","But for","Otherwise"], a:1, e:"Varsayımsal bir durum soruluyor: Supposing (= farz edelim ki) + cümle. Unless anlamı tersine çevirir; but for ardından isim alır; otherwise cümle başında koşul bildirmez."},
  {id:"r-cond-alt-07", sub:"cond-alt", from:["cond-09"], q:"The company has agreed to fund the research ---- the results are shared with its own scientists before publication.", o:["on condition that","in case","unless","otherwise","even though"], a:0, e:"Finansman bir şarta bağlanıyor: on condition that (= şartıyla). unless anlamı tersine çevirir; in case önlem bildirir; even though zıtlık bildirir."},
  {id:"r-cond-alt-08", sub:"cond-alt", from:["cond-11"], q:"Hospitals keep emergency generators ---- the main power supply fails during an operation.", o:["unless","provided that","in case","as long as","but for"], a:2, e:"Jeneratör bulundurmak olası bir elektrik kesintisine karşı önlemdir: in case. provided that / as long as jeneratör bulundurmayı kesinti şartına bağlar, anlam bozulur; unless ise mantıksızdır."},
  {id:"r-cond-alt-09", sub:"cond-alt", from:["cond-11","cond-10"], q:"---- heavy rain, the outdoor concert will be moved to the city's sports hall.", o:["In case","Unless","Provided that","In case of","Otherwise"], a:3, e:"Boşluktan sonra yalnızca isim öbeği (heavy rain) var; isimle kullanılan In case of gerekir. In case, unless ve provided that ardından özne + fiil içeren tam cümle ister."},
  {id:"r-cond-alt-10", sub:"cond-alt", from:["cond-08"], q:"The disease is rarely fatal ---- it is diagnosed at a very late stage.", o:["provided that","unless","as long as","in case","but for"], a:1, e:"Anlam “çok geç teşhis edilmedikçe nadiren ölümcüldür” olmalıdır: unless = if not. provided that / as long as “geç teşhis edilirse nadiren ölümcül” gibi mantıksız bir anlam verir; but for ardından isim alır."},
  {id:"r-cond-alt-11", sub:"cond-alt", from:["cond-09","cond-11"], q:"The bank will lend the company the money ---- it presents a detailed business plan; ----, the application will be rejected.", o:["provided that / otherwise","unless / otherwise","in case / unless","provided that / in case","but for / as long as"], a:0, e:"Kredi bir şarta bağlanıyor (provided that), noktalı virgülden sonra ise “aksi takdirde” anlamı gerekir (otherwise). “unless / otherwise” ilk kısmı tersine çevirir; in case noktalı virgülden sonra tek başına kullanılamaz."},
  {id:"r-cond-alt-12", sub:"cond-alt", from:["cond-10"], q:"---- the invention of the printing press, the ideas of the Reformation would not have spread so rapidly across Europe.", o:["But for","Unless","As long as","Provided","In case"], a:0, e:"Boşluktan sonra isim öbeği var ve ana cümle Type 3; “… olmasaydı” anlamındaki But for (+ isim) gerekir. Unless, as long as ve provided ardından tam cümle ister; in case önlem bildirir."},
  {id:"r-cond-alt-13", sub:"cond-alt", from:["w4-10","cond-08"], q:"Unless governments take urgent action to cut carbon emissions, ----.", o:["the polar ice caps would not have melted so quickly","renewable energy had become cheaper than coal","many species would have survived","so individuals should plant more trees","global temperatures are likely to rise by more than two degrees this century"], a:4, e:"unless = if not; “hükümetler acil önlem almazsa” gerçek bir koşuldur ve olası bir gelecek sonucu ister: sıcaklıklar iki dereceden fazla artacak. “would not have melted” Type 3 sonucudur ve present koşulla uyuşmaz."},
  {id:"r-cond-alt-14", sub:"cond-alt", from:["w4-10","cond-09"], q:"As long as the economy continues to grow at its current rate, ----.", o:["unemployment should keep falling over the next few years","the government would have balanced the budget","inflation had reached record levels","exports fell sharply in the previous decade","investors would not have lost confidence"], a:0, e:"as long as (= sürece) gerçek bir koşul bildirir ve olası bir gelecek sonucu ister: işsizlik düşmeye devam etmeli. “would have balanced” ve “would not have lost” Type 3 sonucudur, present koşulla uyuşmaz."},
  {id:"r-cond-alt-15", sub:"cond-alt", from:["cond-11"], q:"The museum keeps copies of its most valuable manuscripts in a separate building ----.", o:["provided that the originals are destroyed in a fire","unless the originals are stored properly","but for the risk of theft","in case the originals are damaged by fire or flood","so that visitors had seen them"], a:3, e:"Kopya saklamak olası bir hasara karşı alınan önlemdir: in case the originals are damaged. provided that önlemi hasar şartına bağlar ve anlamı bozar; but for Type 2/3 sonuç ister."},
  {id:"r-cond-alt-16", sub:"cond-alt", from:["cond-10"], q:"----, the injured climbers would not have survived the night on the mountain.", o:["Unless the rescue team responds quickly","Provided that the rescue team arrived","Without the quick response of the rescue team","In case of bad weather","As long as the weather remains calm"], a:2, e:"Ana cümle Type 3 (would not have survived); “… olmasaydı” anlamındaki Without + isim öbeği uygundur. “Unless the rescue team responds quickly” Type 1 koşuludur ve geçmiş sonuçla uyuşmaz."},
  {id:"r-cond-alt-17", sub:"cond-alt", from:["cond-09"], q:"The landlord agreed to reduce the rent ---- the tenants carried out the repairs themselves.", o:["unless","in case","otherwise","but for","providing"], a:4, e:"Kira indirimi bir şarta bağlanıyor: providing (= provided that, şartıyla). unless anlamı tersine çevirir; in case önlem bildirir; but for ardından isim alır."},
  {id:"r-cond-alt-18", sub:"cond-alt", from:["cond-11"], q:"The software must be updated regularly. ----, hackers could exploit security weaknesses in older versions.", o:["Unless","Provided that","Otherwise","In case","But for"], a:2, e:"Önceki cümleye “aksi takdirde” anlamıyla bağlanan ve ardından virgül alan Otherwise gerekir. Unless, provided that ve in case bağlaçtır ve ardından yan cümle ister; but for isim alır."},
  {id:"r-cond-alt-19", sub:"cond-alt", from:["cond-08"], q:"The match will go ahead ---- it rains, since the stadium has a retractable roof.", o:["unless","provided that","only if","in case","even if"], a:4, e:"Stadyumun açılır kapanır çatısı var; maç yağmur yağsa bile oynanacak: even if. unless “yağmur yağmazsa” anlamı verir ve çatı bilgisiyle çelişir; only if / provided that maçı yağmur şartına bağlar."},
  {id:"r-cond-alt-20", sub:"cond-alt", from:["cond-09"], q:"Scholarships are awarded ---- students maintain a high grade point average throughout their studies.", o:["unless","in case","only if","even if","otherwise"], a:2, e:"Burs yüksek not ortalaması şartına bağlanıyor: only if (= yalnızca … ise). unless anlamı tersine çevirir; even if şartı önemsizleştirir; in case önlem bildirir."},
  {id:"r-cond-alt-21", sub:"cond-alt", from:["cond-08"], q:"The project will continue ---- the government provides additional funding, as private investors have already covered most of the costs.", o:["whether or not","only if","provided that","unless","in case"], a:0, e:"Özel yatırımcılar maliyeti zaten karşıladığı için proje devlet desteğinden bağımsız sürecek: whether or not (= olsa da olmasa da). only if / provided that projeyi desteğe bağlar ve “as private investors …” gerekçesiyle çelişir."},
  {id:"r-cond-alt-22", sub:"cond-alt", from:["cond-11"], passage:"Earthquakes cannot be predicted with any precision, so preparation is essential in high-risk regions. In Japan, for example, many households keep an emergency kit containing water, food, a torch and basic medical supplies (1) ---- a major tremor cuts off electricity and water supplies for several days. Schools hold regular drills, and new buildings must meet strict engineering standards designed to absorb seismic shocks. As a result, even strong earthquakes often cause far fewer casualties in Japan than in countries with weaker building regulations.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["unless","provided that","as long as","in case","but for"], a:3, e:"Acil durum çantası olası bir depreme karşı alınan önlemdir: in case (= olur da … diye). provided that / as long as çanta bulundurmayı deprem şartına bağlar ve anlam bozulur; but for ardından isim alır."},
  {id:"r-cond-alt-23", sub:"cond-alt", from:["cond-08"], passage:"The Amazon rainforest stores enormous quantities of carbon and produces a significant share of the rainfall on which South American agriculture depends. Over the past fifty years, however, nearly a fifth of the forest has been cleared for cattle ranching, soya plantations and mining. As trees disappear, the region becomes drier, which in turn makes the remaining forest more vulnerable to fire. Climate scientists warn that large parts of the Amazon could turn into dry savannah within a few decades (1) ---- deforestation is brought under control.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["provided that","in case","as long as","unless","because of"], a:3, e:"Anlam “ormansızlaşma kontrol altına alınmazsa savana dönüşebilir” olmalıdır: unless = if not. provided that / as long as “kontrol altına alınırsa dönüşebilir” gibi mantıksız bir anlam verir; because of ardından isim alır."},
  {id:"r-cond-alt-24", sub:"cond-alt", from:["cond-11","cond-10"], q:"---- your flight is cancelled, the airline is required to offer you either a full refund or an alternative flight.", o:["Unless","But for","Otherwise","In case of","In the event that"], a:4, e:"In the event that (= … olması durumunda) ardından tam cümle alır ve anlama uyar. In case of ve but for ardından isim ister; unless anlamı tersine çevirir."},
  {id:"r-cond-alt-25", sub:"cond-alt", from:["cond-10"], q:"But for the invention of refrigeration, ----.", o:["food will spoil more quickly in summer","supermarkets had sold only local produce","it would be much harder to transport fresh food over long distances","people store food in cool cellars","as long as food is kept dry"], a:2, e:"But for (= … olmasaydı) gerçeğe aykırı bir sonuç ister (Type 2/3): taze gıdayı uzak mesafelere taşımak çok daha zor olurdu. “food will spoil” Type 1 sonucudur ve but for ile kullanılamaz."},
  {id:"r-cond-alt-26", sub:"cond-alt", from:["cond-09"], q:"The ceasefire will hold ---- both sides respect the agreed borders.", o:["unless","as long as","in case","otherwise","but for"], a:1, e:"Ateşkesin sürmesi bir şarta bağlanıyor: as long as (= sürece). unless “saygı göstermezlerse sürecek” gibi ters bir anlam verir; in case önlem bildirir; but for ardından isim alır."},
  {id:"r-cond-alt-27", sub:"cond-alt", from:["cond-09","cond-11"], q:"---- the drug proves effective in larger trials, it could transform the treatment of Alzheimer's disease; ----, researchers will have to look for alternative approaches.", o:["Unless / otherwise","Assuming that / otherwise","In case / unless","But for / provided that","Even if / in case"], a:1, e:"İlk kısım olumlu bir varsayım bildirir (Assuming that = … varsayarsak), noktalı virgülden sonra ise “aksi takdirde” anlamı gerekir (otherwise). “Unless / otherwise” ilk kısmı tersine çevirir; in case noktalı virgülden sonra tek başına kullanılamaz."},
  {id:"r-wish-01", sub:"wish", from:["cond-12"], q:"Many commuters wish the city ---- a metro system, as the bus network is overcrowded and unreliable.", o:["has","had","will have","had had","would have had"], a:1, e:"Otobüs ağı şu anda kalabalık; bu şimdiki bir dilektir ve wish + past kullanılır: had. had had geçmişe yönelik pişmanlık bildirir; has ve will have wish ile kullanılmaz."},
  {id:"r-wish-02", sub:"wish", from:["cond-12"], q:"The researchers now wish they ---- a larger sample, since critics have questioned the reliability of their findings.", o:["used","would use","have used","use","had used"], a:4, e:"Çalışma tamamlanmış ve eleştiriler gelmiş; pişmanlık geçmişteki bir tercihe aittir: wish + had V3 (had used). used şimdiki bir dileği bildirir; would use gelecekte bir değişim isteğidir."},
  {id:"r-wish-03", sub:"wish", from:["cond-12"], q:"I wish my neighbours ---- their music so loudly late at night; it keeps the whole building awake.", o:["don't play","wouldn't play","hadn't played","won't play","not to play"], a:1, e:"Başkasının tekrarlayan davranışından şikâyet ediliyor; wish + özne + would (not) V: wouldn't play. hadn't played geçmişe ait bir pişmanlıktır; don't / won't wish ile kullanılmaz."},
  {id:"r-wish-04", sub:"wish", from:["cond-12"], q:"If only the authorities ---- the residents before the dam burst; hundreds of lives could have been saved.", o:["warned","would warn","have warned","warn","had warned"], a:4, e:"“could have been saved” ve “before the dam burst” pişmanlığın geçmişe ait olduğunu gösterir; if only + had V3: had warned. warned şimdiki bir dileği bildirir."},
  {id:"r-wish-05", sub:"wish", from:["cond-12"], q:"If only I ---- the answer to your question, but I'm afraid this is not my area of expertise.", o:["know","knew","had known","would know","will know"], a:1, e:"Konuşmacı şu anda cevabı bilmiyor; şimdiki dilek için if only + past: knew. had known geçmişe ait bir pişmanlık bildirir; know ve will know bu kalıpta kullanılmaz."},
  {id:"r-wish-06", sub:"wish", from:["cond-13"], q:"It's about time the university ---- its outdated library catalogue with a modern digital system.", o:["replaces","had replaced","will replace","replaced","has replaced"], a:3, e:"It's (about/high) time + özne kalıbından sonra anlam şimdi olsa da fiil past simple olur: replaced. replaces sık yapılan present hatasıdır; had replaced geçmişe yönelik pişmanlık gibi okunur."},
  {id:"r-wish-07", sub:"wish", from:["cond-13"], q:"After three years of talks, it is time ---- the negotiations and reach a final agreement.", o:["concluded","to conclude","we conclude","had concluded","concluding"], a:1, e:"It's time kalıbından sonra özne yoksa to + V gelir: to conclude (… and reach). “we conclude” hatalıdır; özneyle kullanılsaydı “we concluded” olmalıydı."},
  {id:"r-wish-08", sub:"wish", from:["cond-14"], q:"I would rather ---- at home this evening, as I have an important exam tomorrow.", o:["to stay","stay","stayed","staying","had stayed"], a:1, e:"would rather + aynı özne yapısında yalın fiil gelir: stay. stayed yalnızca farklı özneyle (I'd rather you stayed) kullanılır; to stay ve staying bu kalıba uymaz."},
  {id:"r-wish-09", sub:"wish", from:["cond-14"], q:"Most employees would rather the company ---- this year's annual meeting online instead of in a distant city.", o:["holds","had held","will hold","to hold","held"], a:4, e:"would rather + farklı özne yapısında şimdiki/gelecek tercih için past simple kullanılır: held. had held geçmişe ait bir tercih bildirir; holds ve will hold bu kalıpta kullanılmaz."},
  {id:"r-wish-10", sub:"wish", from:["cond-14"], q:"She'd rather her son ---- engineering, but he chose to study music instead.", o:["had studied","studied","studies","would study","has studied"], a:0, e:"Oğlunun seçimi geçmişte yapıldı (he chose); geçmişe ait tercih için would rather + farklı özne + had V3: had studied. studied şimdiki/gelecek bir tercih bildirir ve “chose” ile uyuşmaz."},
  {id:"r-wish-11", sub:"wish", from:["cond-12"], q:"The minister now wishes she ---- such controversial remarks during last week's interview.", o:["didn't make","wouldn't make","hasn't made","hadn't made","doesn't make"], a:3, e:"Pişmanlık geçen haftaki röportaja aittir; geçmişe yönelik wish + had V3: hadn't made. didn't make şimdiki bir dileği bildirir; wouldn't make ise gelecekte bir değişim isteğidir."},
  {id:"r-wish-12", sub:"wish", from:["cond-12"], q:"Many elderly people wish they ---- how to use smartphones, as so many services are now available only online.", o:["know","would know","knew","have known","will know"], a:2, e:"Hizmetler şu anda yalnızca çevrim içi; bu şimdiki bir dilektir: wish + past (knew). know, have known ve will know wish ile kullanılmaz; know durum bildiren bir fiil olduğu için wish + would ile de kullanılmaz."},
  {id:"r-wish-13", sub:"wish", from:["cond-12"], q:"I wish the weather ---- warmer yesterday; we could have had the picnic outside.", o:["were","would be","is","has been","had been"], a:4, e:"“yesterday” ve “could have had” dileğin geçmişe ait olduğunu gösterir: wish + had V3 (had been). were şimdiki bir dileği bildirir ve yesterday ile uyuşmaz."},
  {id:"r-wish-14", sub:"wish", from:["cond-12"], q:"Environmentalists wish governments ---- stricter emission limits decades ago, and they also wish ordinary consumers ---- more willing to change their habits today.", o:["had introduced / were","introduced / had been","would introduce / are","had introduced / had been","have introduced / would be"], a:0, e:"İlk dilek geçmişe aittir (decades ago → had introduced), ikincisi şimdiye (today → were). “had introduced / had been” ikinci dileği yanlışlıkla geçmişe taşır ve today ile çelişir."},
  {id:"r-wish-15", sub:"wish", from:["cond-14"], q:"I would sooner walk to work than ---- in heavy traffic for an hour every morning.", o:["sitting","to sit","sit","sat","have sat"], a:2, e:"would sooner / would rather … than kalıbında karşılaştırılan iki eylem de yalın hâlde olur: walk … than sit. sitting ve to sit paralelliği bozar; sat yalnızca farklı özneyle kullanılır."},
  {id:"r-wish-16", sub:"wish", from:["cond-14"], q:"Would you rather I ---- the report myself, or shall I ask one of the interns to do it?", o:["write","to write","wrote","will write","had written"], a:2, e:"would rather + farklı özne (I) yapısında şimdiki/gelecek tercih için past simple gelir: wrote. write sık yapılan hatadır; had written geçmişe ait bir tercih bildirir."},
  {id:"r-wish-17", sub:"wish", from:["cond-12"], q:"Many parents wish they ---- more time with their children, but long working hours make this impossible.", o:["can spend","could spend","could have spent","will spend","spend"], a:1, e:"“make this impossible” durumun şu anda geçerli olduğunu gösterir; şimdiki dilek için wish + could V: could spend. could have spent geçmişe ait bir pişmanlıktır; can ve will wish ile kullanılmaz."},
  {id:"r-wish-18", sub:"wish", from:["cond-12"], q:"Farmers in the region wish it ----; their crops have been suffering from drought for months.", o:["rains","will rain","would rain","has rained","is raining"], a:2, e:"Çiftçiler kontrol edemedikleri bir durumun değişmesini istiyor; wish + would V: would rain. rains, will rain, has rained ve is raining wish ile kullanılmaz."},
  {id:"r-wish-19", sub:"wish", from:["cond-12"], q:"If only the construction workers ---- making so much noise; I can't concentrate on my work.", o:["stop","had stopped","would stop","will stop","have stopped"], a:2, e:"Şu anda süren rahatsız edici bir davranıştan şikâyet ediliyor; if only + would V: would stop. had stopped geçmişe ait bir pişmanlıktır ve “I can't concentrate” ile uyuşmaz."},
  {id:"r-wish-20", sub:"wish", from:["cond-13"], q:"It's high time the outdated regulations ---- by more effective ones.", o:["were replaced","are replaced","had been replaced","will be replaced","be replaced"], a:0, e:"It's high time + özne kalıbında fiil past simple olur; edilgen yapıda were replaced. are replaced sık yapılan present hatasıdır; had been replaced kalıba uymaz."},
  {id:"r-wish-21", sub:"wish", from:["cond-12"], q:"Looking back on her long career, the retired diplomat wishes ----.", o:["she had spent more time learning the languages of the countries where she served","she will write a book about her experiences","she spends more time with her grandchildren","she would have been promoted earlier next year","she has visited every continent"], a:0, e:"“Looking back on her career” geçmişe dönük bir pişmanlık gösterir: wish + had V3 (had spent). “will write”, “spends” ve “has visited” wish ile kullanılmaz; “would have been promoted … next year” zamanca çelişkilidir."},
  {id:"r-wish-22", sub:"wish", from:["cond-13"], q:"Local residents say that it's high time ----.", o:["the authorities took action against illegal logging in the national park","the authorities take action against illegal logging","the authorities had taken action last year","for the authorities taking action","the authorities will take action at last"], a:0, e:"It's high time + özne kalıbında fiil past simple olur: the authorities took action. “take action” sık yapılan present hatasıdır; “had taken … last year” kalıba uymaz."},
  {id:"r-wish-23", sub:"wish", from:["cond-14"], q:"I'd rather you ----.", o:["don't mention our conversation to anyone","not to mention our conversation","won't mention our conversation","didn't mention our conversation to anyone at the office","not mentioning our conversation to anyone"], a:3, e:"would rather + farklı özne yapısında şimdiki/gelecek tercih için past simple gelir: didn't mention. don't / won't mention sık yapılan hatalardır; to'lu ve -ing'li biçimler bu kalıba uymaz."},
  {id:"r-wish-24", sub:"wish", from:["cond-12"], passage:"Surveys of retired people consistently reveal that their deepest regrets concern things they did not do rather than things they did. Many say they wish they (1) ---- more time with family and friends instead of working long hours throughout their careers. Others regret not having travelled or pursued a creative hobby while they were still young and healthy. Psychologists believe that such findings contain an important lesson for younger generations: it is often wiser to take a chance than to spend years wondering what might have happened.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["spent","would spend","had spent","have spent","spend"], a:2, e:"Emekliler kariyerleri boyunca yaptıklarından pişmanlık duyuyor; geçmişe yönelik wish + had V3: had spent. spent şimdiki bir dileği bildirir; would spend gelecekte bir değişim isteğidir."},
  {id:"r-wish-25", sub:"wish", from:["cond-13"], passage:"For decades, scientists have warned that plastic waste is accumulating in the world's oceans at an alarming rate. Millions of tonnes enter the sea each year, harming fish, seabirds and marine mammals, and tiny plastic particles have even been found in human blood. Although some countries have banned single-use plastic bags, global production of plastic continues to rise. Many campaigners argue that it is high time manufacturers (1) ---- full responsibility for the waste their products create, rather than leaving the problem to consumers and local governments.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["take","had taken","will take","have taken","took"], a:4, e:"It's high time + özne kalıbından sonra anlam şimdi olsa da fiil past simple olur: took. take sık yapılan present hatasıdır; had taken geçmişe yönelik bir pişmanlık gibi okunur."},
  {id:"r-wish-26", sub:"wish", from:["cond-14"], q:"A spokesperson said the company would rather ---- on the allegations until the investigation is complete.", o:["not to comment","didn't comment","don't comment","not comment","not commenting"], a:3, e:"would rather + aynı özne yapısında yalın fiil gelir; olumsuzu would rather not + V: not comment. didn't comment yalnızca farklı özneyle kullanılır; not to comment bu kalıba uymaz."},
  {id:"r-wish-27", sub:"wish", from:["cond-12","cond-14"], q:"Now that the project has failed, the investors wish they ---- more attention to the early warnings, and they would rather the media ---- the story any further.", o:["paid / hadn't pursued","had paid / doesn't pursue","would pay / didn't pursue","had paid / didn't pursue","have paid / won't pursue"], a:3, e:"Uyarılara dikkat etmemek geçmişe ait bir pişmanlıktır (had paid); medyanın haberi sürdürmemesi ise ileriye dönük bir tercihtir ve farklı özneyle past gelir (didn't pursue). “paid / hadn't pursued” iki zamanı ters çevirir."},
  {id:"r-inv-01", sub:"inv", from:["cond-15"], q:"No sooner had the new smartphone been released ---- customers began reporting problems with its battery.", o:["when","that","then","as","than"], a:4, e:"No sooner had … kalıbı than ile tamamlanır. when aynı anlamı taşısa da yalnızca Hardly / Scarcely had … when kalıbında kullanılır."},
  {id:"r-inv-02", sub:"inv", from:["cond-15"], q:"---- had the expedition set up camp when a violent storm swept across the glacier.", o:["No sooner","Not only","Only after","Hardly","Rarely"], a:3, e:"Cümledeki when bağlacı Hardly / Scarcely had … when kalıbını gösterir. No sooner aynı anlamı taşısa da than ile kullanılır; Not only but also ister."},
  {id:"r-inv-03", sub:"inv", from:["cond-15"], q:"Not only ---- the new policy reduce unemployment, but it also increased tax revenues.", o:["did","has","was","had","does"], a:0, e:"Not only ile başlayan cümlede yardımcı fiil özneden önce gelir; ana fiil yalın (reduce) ve devamı past (increased) olduğu için did gerekir. does zamanca uyuşmaz; has ve had ardından V3 ister."},
  {id:"r-inv-04", sub:"inv", from:["cond-16"], q:"---- the government to raise taxes further, many small businesses would be forced to close.", o:["Should","Were","Had","Did","If"], a:1, e:"Ana cümle would + V (Type 2) ve boşluktan sonra “to raise” geliyor; Type 2 devrik koşul Were + özne + to V ile kurulur. Should ardından yalın fiil ister; If ile “to raise” kullanılmaz."},
  {id:"r-inv-05", sub:"inv", from:["cond-16","cond-17"], q:"---- the pilot not reacted so quickly, the plane would have crashed into the mountains.", o:["Were","Had","Should","Did","Unless"], a:1, e:"Boşluktan sonra V3 (reacted) ve ana cümlede would have crashed var; Type 3 devrik koşul Had + özne + V3 ile kurulur. Were ve Should ardından V3 gelemez; unless ile not birlikte kullanılmaz."},
  {id:"r-inv-06", sub:"inv", from:["cond-17","w4-11"], q:"Rarely ---- such a large number of migrating birds in a single wetland.", o:["have researchers observed","researchers have observed","researchers observed","did researchers observed","have observed researchers"], a:0, e:"Rarely ile başlayan cümlede yardımcı fiil + özne + fiil sırası gelir: have researchers observed. Düz sıra (researchers have observed) yanlıştır; “did … observed” ise did'den sonra yalın fiil gerektiği için hatalıdır."},
  {id:"r-inv-07", sub:"inv", from:["cond-17"], q:"Little ---- that their accidental discovery would change the course of medical history.", o:["the scientists realised","did the scientists realise","had realised the scientists","the scientists did realise","realised the scientists"], a:1, e:"Olumsuz anlamlı Little ile başlayan cümle devrik olur: did + özne + V (did the scientists realise). Düz sıra (the scientists realised) bu kalıpta yanlıştır."},
  {id:"r-inv-08", sub:"inv", from:["cond-17"], q:"Only by reducing its dependence on imported energy ---- its long-term economic security.", o:["the country can guarantee","can guarantee the country","can the country guarantee","the country guarantees","does the country guarantees"], a:2, e:"Only by … ile başlayan cümlede ana cümle devrik olur: can + özne + V (can the country guarantee). Düz sıra yanlıştır; “does … guarantees” does'tan sonra yalın fiil gerektiği için hatalıdır."},
  {id:"r-inv-09", sub:"inv", from:["w4-11"], q:"Not until the 1960s ---- widely accepted by geologists.", o:["the theory of continental drift was","did the theory of continental drift","has the theory of continental drift been","the theory of continental drift had been","was the theory of continental drift"], a:4, e:"Not until ile başlayan cümlede yardımcı fiil özneden önce gelir; edilgen ve geçmiş zamanda was + özne: was the theory … accepted. “has … been” present perfect olduğu için geçmişteki belirli zamanla (the 1960s) kullanılamaz."},
  {id:"r-inv-10", sub:"inv", from:["cond-17"], q:"Never before ---- so much information been available to ordinary citizens as it is today.", o:["did","was","is","have","has"], a:4, e:"Never before ile başlayan cümle devrik olur ve “been” bir perfect yapıyı gösterir; tekil özne (information) için has gerekir. have özne-fiil uyumunu bozar; did, was ve is “been” ile kullanılamaz."},
  {id:"r-inv-11", sub:"inv", from:["cond-17"], q:"Under no circumstances ---- to leave the building during the fire drill.", o:["students are allowed","students allowed","allowed are students","are students allowed","do students allowed"], a:3, e:"Under no circumstances olumsuz bir ifade olduğundan cümle devrik olur: are + özne + V3 (are students allowed). Düz sıra (students are allowed) bu kalıpta yanlıştır."},
  {id:"r-inv-12", sub:"inv", from:["cond-16"], q:"---- it not for the generous support of volunteers, the charity would have to close many of its shelters.", o:["Had","Should","Were","Did","If"], a:2, e:"Ana cümle would + V (Type 2) ve kalıp “Were it not for” (= If it were not for) biçimindedir. Had it not been for Type 3'tür ve burada “been” yoktur; “If it not for” dilbilgisel olarak yanlıştır."},
  {id:"r-inv-13", sub:"inv", from:["cond-16"], q:"---- it not been for the development of antibiotics, millions more people would have died from infections in the twentieth century.", o:["Were","Should","Did","Had","If"], a:3, e:"Boşluktan sonra “not been” ve ana cümlede would have died (Type 3) var; kalıp Had it not been for'dur. Were it not for Type 2'ye aittir ve “been” almaz."},
  {id:"r-inv-14", sub:"inv", from:["cond-15"], q:"No sooner had the company launched its advertising campaign ----.", o:["when its competitors responded with price cuts","sales increased by twenty percent","than sales of its products began to rise sharply","than it has become the market leader","then customers complained about the adverts"], a:2, e:"No sooner had … kalıbı than + past simple ile tamamlanır: than sales … began. when yalnızca Hardly / Scarcely ile kullanılır; “than it has become” present perfect olduğu için geçmiş anlatımla uyuşmaz."},
  {id:"r-inv-15", sub:"inv", from:["cond-15"], q:"Not only did the earthquake destroy thousands of homes, ----.", o:["but it also damaged the region's water and electricity networks","so the government declared a state of emergency","but the damaged hospitals will be rebuilt","and many people had been injured","but also it damages the roads"], a:0, e:"Not only did … yapısı but (it) also + past ile tamamlanır: but it also damaged. “but also it damages” zamanca uyuşmaz; so ve and kalıbın gerektirdiği but also yapısını kurmaz."},
  {id:"r-inv-16", sub:"inv", from:["cond-17"], q:"Only after the ban on hunting was introduced ----.", o:["the population of the antelope began to recover","did the population of the endangered antelope begin to recover","has the antelope population recovered","when the antelope population started to grow","the hunters were arrested by the police"], a:1, e:"Only after … ile başlayan cümlede ana cümle devrik olur: did + özne + V (did the population … begin). Düz sıra (the population … began) yanlıştır; “has … recovered” present perfect olduğu için geçmiş bağlamla uyuşmaz."},
  {id:"r-inv-17", sub:"inv", from:["cond-17","w4-11"], q:"----, did economists realise how fragile the banking system had become.", o:["When the financial crisis broke out in 2008","Although the crisis had been predicted","Only when the financial crisis broke out in 2008","Since the banks had borrowed heavily","As soon as the crisis broke out"], a:2, e:"Ana cümle devrik (did economists realise); bu sıra ancak Only when gibi kısıtlayıcı bir ifadeyle başlayan cümlede kullanılır. When, since ve as soon as devrik yapı gerektirmez, bu yüzden cümle bozulur."},
  {id:"r-inv-18", sub:"inv", from:["cond-16"], q:"Should you have any questions about your prescription, ----.", o:["you would have consulted your doctor","you had called the helpline","the pharmacist would have explained it","your doctor explained the side effects","please consult your pharmacist before taking the medicine"], a:4, e:"Should + özne + V devrik Type 1 koşuludur (= If you have any questions) ve present/emir kipinde bir sonuç ister: please consult your pharmacist. “would have consulted” Type 3 sonucudur ve Should ile uyuşmaz."},
  {id:"r-inv-19", sub:"inv", from:["cond-17"], q:"Seldom ---- a scientific discovery attracted as much public attention as the detection of gravitational waves in 2015.", o:["did","was","has","had been","is"], a:2, e:"Seldom ile başlayan cümle devrik olur ve ana fiil V3 (attracted) olduğu için has + özne + V3 gerekir. did ardından yalın fiil ister; was ve is attracted ile edilgen anlam verir ve bozulur."},
  {id:"r-inv-20", sub:"inv", from:["cond-17"], q:"So severe ---- that schools across the region were closed for a week.", o:["the snowstorm was","was the snowstorm","did the snowstorm","the snowstorm","had the snowstorm"], a:1, e:"So + sıfat ile başlayan cümlede be fiili özneden önce gelir: So severe was the snowstorm that … Düz sıra (the snowstorm was) yanlıştır; did ve had be fiilinin yerini tutamaz."},
  {id:"r-inv-21", sub:"inv", from:["cond-15"], q:"Hardly ---- the doors of the new museum when long queues formed outside.", o:["had the staff opened","the staff had opened","were the staff opened","have the staff opened","the staff opened"], a:0, e:"Hardly … when kalıbında past perfect devrik yapı kullanılır: had + özne + V3 (had the staff opened). Düz sıra yanlıştır; “have the staff opened” present perfect olduğu için geçmiş anlatımla uyuşmaz."},
  {id:"r-inv-22", sub:"inv", from:["cond-17"], q:"In no way ---- responsible for the damage caused by the storm, according to the court's ruling.", o:["the company was","did the company","the company is","was the company","had the company"], a:3, e:"In no way olumsuz bir ifade olduğundan cümle devrik olur; be fiili özneden önce gelir: was the company. did ve had be fiilinin yerini tutamaz; düz sıra ise yanlıştır."},
  {id:"r-inv-23", sub:"inv", from:["cond-15","cond-17"], q:"Not only ---- in the Arctic melting faster than predicted, but the rate of melting is also accelerating.", o:["the sea ice is","does the sea ice","has the sea ice","the sea ice has","is the sea ice"], a:4, e:"Not only ile başlayan cümlede yardımcı fiil özneden önce gelir; fiil -ing (melting) olduğu için is gerekir: is the sea ice melting. does ve has -ing ile kullanılmaz; düz sıra yanlıştır."},
  {id:"r-inv-24", sub:"inv", from:["w4-11","cond-17"], passage:"The discovery of penicillin is one of the most famous accidents in the history of science. In 1928, the Scottish bacteriologist Alexander Fleming returned from a holiday to find that mould had contaminated one of his bacterial cultures. Around the mould, the bacteria had been destroyed. However, Fleming was unable to produce the substance in large quantities, and (1) ---- that penicillin could be manufactured on an industrial scale. By the end of the Second World War, it was saving the lives of thousands of soldiers.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["only in the early 1940s researchers at Oxford showed","not until the early 1940s researchers at Oxford showed","only in the early 1940s have researchers at Oxford shown","only in the early 1940s did researchers at Oxford show","researchers at Oxford did show only when"], a:3, e:"Only / Not until + zaman ifadesiyle başlayan yan cümlede yardımcı fiil özneden önce gelir: did researchers … show. Düz sıralı seçenekler yanlıştır; “have … shown” present perfect olduğu için 1940'lar ile uyuşmaz."},
  {id:"r-inv-25", sub:"inv", from:["cond-15"], passage:"The Industrial Revolution transformed the way goods were produced. In the textile industry, a series of inventions in the eighteenth century allowed factories to spin and weave cloth far faster than skilled workers could by hand. (1) ---- than production costs fell dramatically, making cotton clothing affordable for ordinary families for the first time. However, the new factories also brought long working hours, dangerous conditions and child labour, problems that reformers struggled to address for much of the following century.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Hardly had the new machines been introduced","No sooner the new machines had been introduced","As soon as the new machines were introduced","Only after the new machines were introduced","No sooner had the new machines been introduced"], a:4, e:"Boşluktan sonra than geldiği için No sooner had + özne + V3 kalıbı gerekir. Hardly aynı anlamı taşısa da when ile kullanılır; “No sooner the new machines had” devrik yapıyı kurmadığı için yanlıştır."},
  {id:"r-inv-26", sub:"inv", from:["cond-16"], q:"---- any of the participants experience serious side effects, the trial will be suspended immediately.", o:["Were","Had","Unless","Should","Did"], a:3, e:"Boşluktan sonra yalın fiil (experience) geliyor ve ana cümle will içeriyor; Type 1 devrik koşul Should + özne + V ile kurulur. Were ve Had ardından yalın fiil gelemez; unless anlamı mantıksız kılar."},
  {id:"r-inv-27", sub:"inv", from:["cond-15"], q:"Not only ---- the new drug relieve pain, but it ---- reduces inflammation in the joints.", o:["does / also","is / too","has / also","did / either","does / as well as"], a:0, e:"Not only + does + özne + V yapısı present (reduces) ile uyumludur ve ikinci kısım but it also ile tamamlanır: does / also. did devamdaki reduces ile zamanca uyuşmaz; has ardından yalın fiil gelemez."}
);
